definition.script:
import groovy.json.JsonSlurper;

def targetStack
def infrastructureGitHash

pipeline {
    agent any

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Retrieve Stack') {
            steps {
                script {
                    targetStack = sh(script: """
                    bash -c '
                    set +x

                    if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                        echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                        exit 1
                    fi

                    for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                        chmod +x "\$script_file"
                        if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                            . "\$script_file"
                        fi
                    done

                    get_stack \"${TARGET_STACK}\"
                    '
                    """, returnStdout: true).trim()

                    println "TARGET_STACK: $targetStack"
                }
            }
        }

        stage('Resolve Infrastructure Git Hash') {
            steps {
                script {
                    if (params.INFRASTRUCTURE_GIT_HASH?.trim()) {
                        infrastructureGitHash = params.INFRASTRUCTURE_GIT_HASH.trim()
                        echo "Using provided INFRASTRUCTURE_GIT_HASH: ${infrastructureGitHash}"
                    } else {
                        def result = build job: 'Retrieve Build Spec'
                        copyArtifacts filter: 'build-spec.json', projectName: 'Retrieve Build Spec', selector: specific("" + result.number)
                        def buildSpec = new JsonSlurper().parse(new File("${env.WORKSPACE}/build-spec.json"))
                        infrastructureGitHash = buildSpec.infrastructure_git_hash
                        echo "Resolved INFRASTRUCTURE_GIT_HASH from release control: ${infrastructureGitHash}"
                    }
                }
            }
        }

        stage('Rotate Shared Secrets and Redeploy') {
            steps {
                script {
                    lock("stack-${targetStack}") {
                        build job: 'Render PIC-SURE Configuration', parameters: [
                            [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructureGitHash],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPERATIONS', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_QUERY', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_VISUALIZATION', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_LOGGING', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_DICTIONARY', value: false],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_SHARED_SECRETS', value: true]
                        ]

                        build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: true],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: true],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: true]
                        ]

                        build job: 'PIC-SURE Logging Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                        ]
                    }
                }
            }
        }

        /*
         * configs/pic-sure-logging/logging.env carries no stack segment, so the stage above rewrote
         * the one object both stacks read. The other stack still runs gateway, visualization and
         * pic-sure-logging on the old key, so this stage renders and redeploys those three there.
         * That render does not rotate: it reads the key just minted back rather than minting another.
         */
        stage('Reconcile Other Stack') {
            steps {
                script {
                    if (targetStack != 'a' && targetStack != 'b') {
                        error("Resolved stack '${targetStack}' is neither a nor b, so the other stack cannot be derived. LOGGING_API_KEY has already been rotated in an S3 object that every stack reads; stopping here leaves the other stack presenting the old key, and pic-sure-logging answers those audit events with 401 while the logging client drops them. Reconcile that stack by hand before it is deployed again.")
                    }

                    def otherStack = targetStack == 'a' ? 'b' : 'a'
                    echo "Reconciling stack ${otherStack} onto the rotated LOGGING_API_KEY"

                    lock("stack-${otherStack}") {
                        build job: 'Render PIC-SURE Configuration', parameters: [
                            [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructureGitHash],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: otherStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPERATIONS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_QUERY', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_VISUALIZATION', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_LOGGING', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_DICTIONARY', value: false],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_SHARED_SECRETS', value: false]
                        ]

                        build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: otherStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: false],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: false],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: true]
                        ]

                        build job: 'PIC-SURE Logging Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: otherStack]
                        ]
                    }
                }
            }
        }
    }
}
